"use client";

import { forwardRef } from "react";
import { aspectRatioDefaults, type AspectRatioSpecProps } from "../generated/aspect-ratio.types";
import { cx } from "../utils/cx";

export interface AspectRatioProps
  extends AspectRatioSpecProps,
    Omit<React.HTMLAttributes<HTMLDivElement>, keyof AspectRatioSpecProps | "className"> {
  className?: string;
}

const presets = {
  square: "1 / 1",
  video: "16 / 9",
  photo: "3 / 2",
  wide: "21 / 9",
  portrait: "3 / 4",
} as const;

function toCss(ratio: AspectRatioSpecProps["ratio"]): string {
  if (typeof ratio === "number") return ratio > 0 ? String(ratio) : presets.video;
  if (ratio && ratio in presets) return presets[ratio as keyof typeof presets];
  if (typeof ratio === "string") {
    const [w, h] = ratio.split("/").map((n) => Number(n.trim()));
    if (w > 0 && h > 0) return `${w} / ${h}`;
  }
  return presets.video;
}

/** Keeps its content at a fixed width to height ratio. Images, video and iframes inside fill the box. */
export const AspectRatio = forwardRef<HTMLDivElement, AspectRatioProps>(function AspectRatio(
  { ratio = aspectRatioDefaults.ratio, rounded = aspectRatioDefaults.rounded, children, className, style, ...rest },
  ref,
) {
  return (
    <div
      {...rest}
      ref={ref}
      style={{ aspectRatio: toCss(ratio), ...style }}
      className={cx(
        "relative w-full overflow-hidden " +
          "[&>img]:size-full [&>img]:object-cover [&>video]:size-full [&>video]:object-cover [&>iframe]:size-full [&>iframe]:border-0 " +
          "[&>svg]:size-full [&>canvas]:size-full",
        rounded && "rounded-[var(--rd-radius-control)]",
        className,
      )}
    >
      {children}
    </div>
  );
});

// Generated by rdloom codegen from specs/aspect-ratio.spec.json (v0.1.0).
// Do not edit. Change the spec and run `npm run gen`.

import type { ReactNode } from "react";

/** A box that keeps a fixed width to height ratio for what it holds, such as an image, a video or a map. It reserves the space before the content loads, so the page does not jump. */
export interface AspectRatioSpecProps {
  /**
   * Width divided by height as a number (1.5), a "16/9" string, or a preset: square 1/1, video 16/9, photo 3/2, wide 21/9, portrait 3/4.
   * @default "video"
   */
  ratio?: number | "square" | "video" | "photo" | "wide" | "portrait" | `${number}/${number}`;
  /**
   * Rounds the corners with the control radius.
   * @default false
   */
  rounded?: boolean;
  /**
   * The content. Images, video and iframes are stretched to fill the box and cropped to cover it.
   */
  children?: ReactNode;
}

export const aspectRatioDefaults = {
  ratio: "video",
  rounded: false,
} as const;

export const aspectRatioMeta = {
  "name": "AspectRatio",
  "version": "0.1.0",
  "status": "experimental",
  "role": "none"
} as const;

