import { CustomerTable, type Customer } from "@rdloom/react";

const people = [
  ["Ada Lovelace", "Analytical Co"], ["Grace Hopper", "Compiler Labs"], ["Katherine Johnson", "Orbit Systems"], ["Alan Turing", "Enigma Works"],
  ["Margaret Hamilton", "Apollo Software"], ["Dennis Ritchie", "Bell Studio"], ["Barbara Liskov", "Substitution Inc"], ["Edsger Dijkstra", "Shortest Path"],
  ["Radia Perlman", "Spanning Tree"], ["Donald Knuth", "Literate Press"], ["Frances Allen", "Optimise Ltd"], ["Linus Torvalds", "Kernel House"],
  ["Hedy Lamarr", "Spread Spectrum"], ["Tim Berners-Lee", "Web Works"], ["Annie Easley", "Rocket Code"], ["Ken Thompson", "Pipe Dream"],
  ["Shafi Goldwasser", "Zero Knowledge"], ["Vint Cerf", "Packet Co"], ["Mary Jackson", "Wind Tunnel"], ["John McCarthy", "Lisp Labs"],
  ["Sophie Wilson", "Instruction Set"], ["Guido van Rossum", "Indent Inc"], ["Evelyn Boyd Granville", "Orbit Maths"], ["Niklaus Wirth", "Pascal Press"],
];
const plans = ["Free", "Pro", "Team", "Enterprise"];
const price = [0, 29, 99, 499];
const statuses = ["active", "active", "trial", "overdue", "active", "churned", "active"];

// Every customer has a plan, a status, monthly revenue and a join date. The block does the rest.
const customers: Customer[] = people.map(([name, company], i) => {
  const plan = i % 4;
  return {
    id: `c${i + 1}`,
    name,
    company,
    email: `${name.split(" ")[0].toLowerCase()}@example.com`,
    plan: plans[plan],
    status: statuses[i % statuses.length],
    mrr: price[plan],
    joinedAt: `2026-${String(1 + (i % 9)).padStart(2, "0")}-${String(3 + ((i * 5) % 24)).padStart(2, "0")}`,
  };
});

export default function CustomerTableBasicExample() {
  return (
    <div className="mx-auto w-[60rem] max-w-full">
      <CustomerTable customers={customers} pageSize={8} />
    </div>
  );
}

import { useEffect, useRef, useState } from "react";
import { CustomerTable, applyCustomerQuery, type Customer, type CustomerQuery } from "@rdloom/react";

const all: Customer[] = Array.from({ length: 240 }, (_, i) => ({
  id: `c${i + 1}`,
  name: `Customer ${String(i + 1).padStart(3, "0")}`,
  email: `customer${i + 1}@example.com`,
  plan: ["Free", "Pro", "Team"][i % 3],
  status: ["active", "trial", "overdue", "churned"][i % 4],
  mrr: [0, 29, 99][i % 3],
  joinedAt: `2026-0${1 + (i % 9)}-${String(1 + (i % 27)).padStart(2, "0")}`,
}));

// A stand-in for your API: it answers after a short wait. In your app, send the query to the server and
// return that page and the number of matches. (applyCustomerQuery is the same logic the table uses in memory.)
const fetchCustomers = (query: CustomerQuery) =>
  new Promise<{ rows: Customer[]; total: number }>((resolve) => {
    const { rows, total } = applyCustomerQuery(all, query);
    setTimeout(() => resolve({ rows, total }), 600);
  });

export default function CustomerTableServerSideExample() {
  const [page, setPage] = useState<{ rows: Customer[]; total: number }>({ rows: [], total: 0 });
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string>();
  const last = useRef<CustomerQuery | undefined>(undefined);

  const load = (query: CustomerQuery) => {
    last.current = query;
    setLoading(true);
    setError(undefined);
    fetchCustomers(query)
      .then((result) => last.current === query && setPage(result)) // ignore an answer that arrives late
      .catch(() => setError("The server did not answer."))
      .finally(() => last.current === query && setLoading(false));
  };
  useEffect(() => load({ search: "", status: [], plan: [], sort: null, page: 1, pageSize: 8 }), []);

  return (
    <div className="mx-auto w-[60rem] max-w-full">
      <CustomerTable
        customers={page.rows}
        totalCount={page.total}
        pageSize={8}
        serverSide
        isLoading={loading}
        error={error}
        onRetry={() => last.current && load(last.current)}
        onQueryChange={load}
        // The cards above the table would only describe this one page: leave them out, or pass the totals your API returns.
        insights="none"
        onExport={(rows) => console.log(`Export ${rows.length} customers`)}
      />
    </div>
  );
}

import { useState } from "react";
import { Button, CustomerTable } from "@rdloom/react";

// While data is on its way pass isLoading: rows turn into skeletons and the controls wait.
// With no customers the table says so in words and, when a filter hides everyone, offers to clear it.
export default function CustomerTableLoadingAndEmptyExample() {
  const [state, setState] = useState<"loading" | "empty" | "error">("loading");
  return (
    <div className="mx-auto flex w-[60rem] max-w-full flex-col gap-4">
      <div role="group" aria-label="State to show" className="flex gap-2">
        {(["loading", "empty", "error"] as const).map((s) => (
          <Button key={s} size="sm" variant={state === s ? "primary" : "secondary"} onPress={() => setState(s)}>
            {s[0].toUpperCase() + s.slice(1)}
          </Button>
        ))}
      </div>
      <CustomerTable
        customers={[]}
        insights="none"
        isLoading={state === "loading"}
        error={state === "error" ? "The server did not answer." : undefined}
        onRetry={() => setState("loading")}
      />
    </div>
  );
}

import { CustomerTable, type Customer, type CustomerInsights } from "@rdloom/react";

const customers: Customer[] = [
  { id: "1", name: "Ada Lovelace", email: "ada@example.com", plan: "Pro", status: "active", mrr: 99, joinedAt: "2026-01-14" },
