import { useState } from "react";
import { Alert, CustomerTable, type Customer } from "@rdloom/react";

const customers: Customer[] = [
  { id: "1", name: "Ada Lovelace", email: "ada@example.com", company: "Analytical Co", plan: "Pro", status: "active", mrr: 99, joinedAt: "2026-01-14" },
  { id: "2", name: "Grace Hopper", email: "grace@example.com", company: "Compiler Labs", plan: "Team", status: "active", mrr: 499, joinedAt: "2026-02-02" },
  { id: "3", name: "Alan Turing", email: "alan@example.com", plan: "Free", status: "trial", mrr: 0, joinedAt: "2026-03-09" },
];

// onOpenCustomer turns each name into a button. What it opens (a panel, a page, a dialog) is up to you.
export default function CustomerTableRowActionExample() {
  const [open, setOpen] = useState<Customer | null>(null);
  return (
    <div className="mx-auto flex w-[56rem] max-w-full flex-col gap-4">
      {open && (
        <Alert title={open.name} onDismiss={() => setOpen(null)}>
          {open.email}, on the {open.plan} plan.
        </Alert>
      )}
      <CustomerTable customers={customers} insights="none" onOpenCustomer={setOpen} />
    </div>
  );
}

import { useState } from "react";
import {
  CustomerTable,
  customerQueryFromUrl,
  customerQuerySchema,
  customerQueryToUrl,
  useQueryState,
  type Customer,
} from "@rdloom/react";

const names = ["Ada Lovelace", "Grace Hopper", "Katherine Johnson", "Alan Turing", "Margaret Hamilton", "Dennis Ritchie", "Barbara Liskov", "Edsger Dijkstra", "Radia Perlman", "Donald Knuth", "Frances Allen", "Hedy Lamarr"];
const plans = ["Free", "Pro", "Team", "Enterprise"];
const price = [0, 29, 99, 499];
const statuses = ["active", "active", "trial", "overdue", "active", "churned"];

const customers: Customer[] = names.map((name, i) => ({
  id: `c${i + 1}`,
  name,
  email: `${name.split(" ")[0].toLowerCase()}@example.com`,
  plan: plans[i % 4],
  status: statuses[i % statuses.length],
  mrr: price[i % 4],
  joinedAt: `2026-${String(1 + (i % 9)).padStart(2, "0")}-${String(3 + ((i * 5) % 24)).padStart(2, "0")}`,
}));

// The search, filters, sort and page live in the address. Here the "address" is a string kept in state so the
// preview can show it; in your app pass useWindowQueryState(customerQuerySchema), or your router's search params.
export default function CustomerTableUrlStateExample() {
  const [search, setSearch] = useState("");
  const [state, setState] = useQueryState(customerQuerySchema, { search, onChange: setSearch });

  return (
    <div className="flex w-full justify-center">
      <div className="flex w-[60rem] max-w-full flex-col gap-4">
        <p className="rounded-[var(--rd-radius-control)] bg-[var(--rd-color-surface-subtle)] px-3 py-2 font-mono text-sm text-[var(--rd-color-text-muted)]">
          /customers{search ? `?${search}` : ""}
        </p>
        <CustomerTable
          customers={customers}
          pageSize={5}
          insights="none"
          query={customerQueryFromUrl(state, 5)}
          onQueryChange={(query) => setState(customerQueryToUrl(query))}
        />
      </div>
    </div>
  );
}

import { CustomerTable, type Customer } from "@rdloom/react";

const customers: Customer[] = [
  { id: "1", name: "Ada Lovelace", email: "ada@example.com", company: "Analytical Co", plan: "Pro", status: "active", mrr: 99, joinedAt: "2026-01-14" },
  { id: "2", name: "Grace Hopper", email: "grace@example.com", company: "Compiler Labs", plan: "Team", status: "active", mrr: 499, joinedAt: "2026-02-02" },
  { id: "3", name: "Alan Turing", email: "alan@example.com", plan: "Free", status: "trial", mrr: 0, joinedAt: "2026-03-09" },
];

// The app answers per action. Here this person may look but not open a customer, and Export is shown with the reason it is off.
// The server must check both again: what the page shows is not security.
export default function CustomerTablePermissionsExample() {
  return (
    <div className="mx-auto w-[56rem] max-w-full">
      <CustomerTable
        customers={customers}
        insights="none"
        onSelect={() => {}}
        permissions={{ open: "disabled", export: { state: "disabled", reason: "Only admins can export customers" } }}
      />
    </div>
  );
}

import { CustomerTable, type Customer } from "@rdloom/react";

const customers: Customer[] = [
  { id: "1", name: "Ada Lovelace", email: "ada@example.com", company: "Analytical Co", plan: "Pro", status: "active", mrr: 99, joinedAt: "2026-01-14" },
  { id: "2", name: "Grace Hopper", email: "grace@example.com", company: "Compiler Labs", plan: "Team", status: "active", mrr: 499, joinedAt: "2026-02-02" },
  { id: "3", name: "Alan Turing", email: "alan@example.com", plan: "Free", status: "trial", mrr: 0, joinedAt: "2026-03-09" },
];

// classNames restyles one part without editing the file: a tinted table header and a different row hover.
export default function CustomerTableClassNamesExample() {
  return (
    <div className="mx-auto w-[56rem] max-w-full">
      <CustomerTable
        customers={customers}
        insights="none"
        classNames={{
          table: "[&_[role=columnheader]]:bg-[var(--rd-color-surface-selected)] [&_[role=row]]:data-[hovered]:bg-[var(--rd-color-surface-subtle)]",
          toolbar: "rounded-xl bg-[var(--rd-color-surface-subtle)] p-2",
        }}
      />
    </div>
  );
}

