export default function DashboardShellWithYourRouterExample() {
  const [path, setPath] = useState("/people");

  const Link = ({ href, className, children, onClick }: { href: string; className: string; children: ReactNode; onClick: () => void }) => (
    <a
      href={href}
      className={className}
      onClick={(event) => {
