   * The columns: { id, header, cell?(row), value?(row), sortable?, align?, hideOnMobile?, width? }. The first column names each row (and is the title of a phone card). value is what sorting, searching and the CSV read; without it the row's field named id is used.
   */
  columns: import("../data-table/query").DataTableColumn<any>[];
  /**
   * A stable, unique id for a row, such as its database id. Used for selection, focus after a delete and the open link.
   */
  getRowId: (row: any) => string;
  /**
   * Accessible name of the table and the section, e.g. "Orders".
   * @default "Table"
   */
  label?: string;
  /**
   * The data state, when your data layer gives you one: loading, empty, error or ready. It wins over isLoading and error. A ready table with no matching rows says nothing matches.
   */
  state?: import("../utils/state").DataState;
  /**
   * Show loading rows and skeleton cards, disable the controls, and mark the section busy.
   * @default false
   */
  isLoading?: boolean;
  /**
   * Something went wrong loading: a message to show instead of the rows (true uses a general one).
   */
  error?: string | boolean;
  /**
   * Adds a Try again button to the error state.
   */
  onRetry?: () => void;
  /**
   * Title shown when there are no rows at all. Defaults to "Nothing here yet".
   */
  emptyTitle?: string;
  /**
   * Text under the empty title.
   */
  emptyDescription?: string;
  /**
   * A control shown in the empty state when there are no rows at all (not when a search found nothing), such as an Add button.
   */
  emptyAction?: import("react").ReactNode;
  /**
   * Add a search box. true looks in every column; or list the column ids to look in.
   */
  searchable?: boolean | string[];
  /**
   * Placeholder of the search box.
   * @default "Search"
   */
  searchPlaceholder?: string;
  /**
