   */
  classNames?: Partial<Record<"root" | "toolbar" | "search" | "filters" | "count" | "export" | "bulk-bar" | "table" | "header" | "row" | "cell" | "cards" | "card" | "empty" | "error" | "footer" | "pagination", string>>;
  /**
   * Row spacing of the table.
   * @default "standard"
   */
  density?: "compact" | "standard" | "comfortable";
  /**
   * Table or cards. auto shows cards when the block itself is narrower than about 640px (not just the screen).
   * @default "auto"
   */
  layout?: "auto" | "table" | "cards";
}

export const dataTableDefaults = {
  label: "Table",
  isLoading: false,
  searchPlaceholder: "Search",
  pageSize: 10,
  serverSide: false,
  selectionMode: "none",
  density: "standard",
  layout: "auto",
} as const;

export const dataTableMeta = {
  "name": "DataTable",
  "version": "0.1.0",
  "status": "experimental",
  "role": "region"
