export const removeButton =
  "flex size-8 shrink-0 items-center justify-center rounded-[var(--rd-radius-control)] outline-none " +
  "text-[var(--rd-color-text-muted)] data-[hovered]:bg-[var(--rd-color-surface-subtle)] data-[hovered]:text-[var(--rd-color-text-default)] " +
  "data-[focus-visible]:ring-2 data-[focus-visible]:ring-[var(--rd-color-focus-ring)]";

export interface FooterProps {
  access: ResolvedPermission;
  classNames?: InviteClassNames;
  /** Shown at the start of the footer, for example a count. */
  start?: ReactNode;
  secondaryLabel: string;
  onSecondary: () => void;
  /** "submit" sends the form; otherwise a plain button with this label and action. */
  primary: { kind: "submit"; label: string; isDisabled?: boolean } | { kind: "button"; label: string; onPress: () => void; isDisabled?: boolean };
  /** Two buttons of the same width, filling the row. */
  equal?: boolean;
}

export function Footer({ access, classNames, start, secondaryLabel, onSecondary, primary, equal }: FooterProps) {
  const { isPending } = useFormState();
  const reasonId = useId();
  const showReason = access.isDisabled && access.reason && primary.kind === "submit";
  return (
    <>
      {showReason && (
        <p id={reasonId} className={cx("text-sm text-[var(--rd-color-text-muted)]", classNames?.reason)}>
          {access.reason}
        </p>
      )}
      <div className={cx(equal ? "grid grid-cols-2 gap-3" : "flex flex-wrap items-center justify-end gap-2", classNames?.actions)}>
        {start && <div className="me-auto min-w-0 text-sm text-[var(--rd-color-text-muted)]">{start}</div>}
        <Button
          type="button"
          variant="secondary"
          isDisabled={isPending}
          onPress={onSecondary}
          className={cx(equal && "w-full", classNames?.cancelButton)}
        >
          {secondaryLabel}
        </Button>
        {primary.kind === "button" ? (
          <Button type="button" isDisabled={primary.isDisabled} onPress={primary.onPress} className={cx(equal && "w-full", classNames?.submitButton)}>
            {primary.label}
          </Button>
        ) : primary.isDisabled ? (
          <Button type="button" isDisabled className={cx(equal && "w-full", classNames?.submitButton)}>
            {primary.label}
          </Button>
        ) : access.isDisabled ? (
          // Looks disabled but stays in the tab order, so the reason can be reached.
          <Button
            type="button"
            aria-disabled="true"
            aria-describedby={access.reason ? reasonId : undefined}
            onPress={() => {}}
            className={cx("opacity-50 cursor-not-allowed", equal && "w-full", classNames?.submitButton)}
          >
            {primary.label}
          </Button>
        ) : (
          <FormSubmitButton className={cx(equal && "w-full", classNames?.submitButton)}>{primary.label}</FormSubmitButton>
        )}
      </div>
    </>
  );
}

"use client";

import { useEffect, useRef, useState, type KeyboardEvent } from "react";
import { ListBox, ListBoxItem, Button as AriaButton } from "react-aria-components";
import { Avatar } from "../avatar/avatar";
import { cx } from "../utils/cx";
import { CheckIcon, CloseIcon, PlusIcon } from "../utils/icons";
import {
  RoleSelect,
  ScrollList,
  SearchBox,
  emailShape,
  people as countPeople,
  removeButton,
  type InviteClassNames,
  type InvitePerson,
  type InviteRole,
} from "./invite-parts";

export interface PickedPerson {
  email: string;
  role: string;
  person?: InvitePerson;
}

interface SearchPickerProps {
  directory: InvitePerson[];
  onSearch?: (query: string) => InvitePerson[] | Promise<InvitePerson[]>;
  roles: InviteRole[];
  picked: PickedPerson[];
  onPicked: (next: PickedPerson[]) => void;
  startRole: string;
  known: Set<string>;
  maxInvites: number;
  maxVisibleRows: number;
  classNames?: InviteClassNames;
}

const key = (email: string) => email.trim().toLowerCase();

/** The search variant: look people up, pick them into a to-invite list with a role each. */
export function SearchPicker({
  directory,
  onSearch,
  roles,
  picked,
  onPicked,
  startRole,
  known,
  maxInvites,
  maxVisibleRows,
  classNames,
}: SearchPickerProps) {
  const [query, setQuery] = useState("");
  const [found, setFound] = useState<InvitePerson[]>(directory);
  const [loading, setLoading] = useState(false);
  const [announcement, setAnnouncement] = useState("");
  const latest = useRef(0);
  const results = useRef<HTMLDivElement>(null);

  useEffect(() => {
    const q = query.trim();
    const run = ++latest.current;
    if (onSearch && q) {
      setLoading(true);
      Promise.resolve(onSearch(q))
        .then((list) => {
          if (run === latest.current) setFound(list);
        })
        .catch(() => {
          if (run === latest.current) setFound([]);
        })
        .finally(() => {
          if (run === latest.current) setLoading(false);
        });
      return;
    }
    setLoading(false);
    const lower = q.toLowerCase();
    setFound(lower ? directory.filter((p) => p.name.toLowerCase().includes(lower) || p.email.toLowerCase().includes(lower)) : directory);
  }, [query, onSearch, directory]);

  const chosen = new Set(picked.map((p) => key(p.email)));
  const atMax = picked.length >= maxInvites;
  const visible = found.filter((p) => !known.has(key(p.email)));
  const typed = query.trim();
  const offerEmail =
    emailShape.test(typed) &&
    !known.has(key(typed)) &&
    !chosen.has(key(typed)) &&
    !visible.some((p) => key(p.email) === key(typed)) &&
    !directory.some((p) => key(p.email) === key(typed));

  const add = (person: InvitePerson | undefined, email: string) => {
    if (chosen.has(key(email))) return;
    if (atMax) {
      setAnnouncement(`You can invite up to ${maxInvites} people at once.`);
      return;
    }
    onPicked([...picked, { email, role: startRole, person }]);
    setAnnouncement(`${person?.name ?? email} added. ${countPeople(picked.length + 1)} to invite.`);
  };
  const remove = (email: string, name: string) => {
    onPicked(picked.filter((p) => key(p.email) !== key(email)));
    setAnnouncement(`${name} removed.`);
  };

  const first = visible[0];
  const onSearchKey = (event: KeyboardEvent) => {
    if (event.key === "Enter") {
      event.preventDefault();
      if (!typed) return;
      if (first) add(first, first.email);
      else if (offerEmail) add(undefined, typed);
    } else if (event.key === "ArrowDown") {
      const option = results.current?.querySelector<HTMLElement>('[role="option"]');
      if (option) {
        event.preventDefault();
        option.focus();
      }
    }
  };

  return (
    <div className="flex min-w-0 flex-col gap-4">
      <div className={cx("flex flex-col gap-2", classNames?.search)}>
        <SearchBox label="Search people" placeholder="Search by name or email" value={query} onChange={setQuery} onKeyDown={onSearchKey} autoFocus />
        <div ref={results} className={classNames?.results}>
          <ScrollList rows={3} rowHeight="2.75rem" gap="0.125rem" watch={`${query}${visible.length}${loading}`}>
            <ListBox
              aria-label="Search results"
              selectionMode="none"
              onAction={(id) => {
                if (id === "__email") return add(undefined, typed);
                const person = visible.find((p) => p.id === id);
                if (person) add(person, person.email);
              }}
              className="flex flex-col gap-0.5 outline-none"
              renderEmptyState={() => (
                <p className="px-2 py-3 text-center text-sm text-[var(--rd-color-text-muted)]">{loading ? "Searching" : "No one found."}</p>
              )}
            >
              {visible.map((p) => {
                const added = chosen.has(key(p.email));
                return (
                  <ListBoxItem key={p.id} id={p.id} textValue={added ? `${p.name}, ${p.email}, added` : `${p.name}, ${p.email}`} className={resultRow}>
                    <Avatar name={p.name} src={p.avatarUrl} size="sm" decorative />
                    <span className="min-w-0 flex-1 truncate font-medium">{p.name}</span>
                    <span className="hidden min-w-0 truncate text-[var(--rd-color-text-muted)] sm:block">{p.email}</span>
                    {added && <CheckIcon />}
                  </ListBoxItem>
                );
              })}
              {offerEmail && (
                <ListBoxItem id="__email" textValue={`Invite ${typed}`} className={resultRow}>
                  <span aria-hidden="true" className="flex size-8 shrink-0 items-center justify-center rounded-full border border-dashed border-[var(--rd-color-border-strong)]">
                    <PlusIcon className="size-4 text-[var(--rd-color-text-muted)]" />
                  </span>
                  <span className="min-w-0 flex-1 truncate">
                    Invite <span className="font-medium">{typed}</span>
                  </span>
                </ListBoxItem>
              )}
            </ListBox>
          </ScrollList>
        </div>
      </div>

      <div className={cx("flex flex-col gap-2", classNames?.list)}>
        <div className="flex items-baseline justify-between gap-2">
          <h3 className="text-sm font-medium">To invite</h3>
          <span className={cx("text-xs text-[var(--rd-color-text-muted)]", classNames?.counter)}>{countPeople(picked.length)}</span>
        </div>
        {picked.length === 0 ? (
          <p className="rounded-[var(--rd-radius-control)] border border-dashed border-[var(--rd-color-border-default)] px-3 py-4 text-center text-sm text-[var(--rd-color-text-muted)]">
            No one yet. Search above and pick people.
          </p>
        ) : (
          <ScrollList rows={maxVisibleRows} rowHeight="2.5rem" watch={picked.length}>
            <ul className="flex flex-col gap-2">
              {picked.map((entry) => {
                const name = entry.person?.name ?? entry.email;
                return (
                  <li key={key(entry.email)} className="flex items-center gap-2">
                    <Avatar name={name} src={entry.person?.avatarUrl} size="sm" decorative />
                    <div className="min-w-0 flex-1 text-sm leading-tight">
                      <div className="truncate font-medium">{name}</div>
                      {entry.person && <div className="truncate text-xs text-[var(--rd-color-text-muted)]">{entry.email}</div>}
                    </div>
                    <RoleSelect
                      label={`Role for ${name}`}
                      roles={roles}
                      value={entry.role}
                      onChange={(role) => onPicked(picked.map((p) => (p === entry ? { ...p, role } : p)))}
                      className="w-32 shrink-0 sm:w-36"
                    />
                    <AriaButton aria-label={`Remove ${name}`} onPress={() => remove(entry.email, name)} className={removeButton}>
                      <CloseIcon className="size-4" />
                    </AriaButton>
                  </li>
                );
              })}
            </ul>
          </ScrollList>
        )}
        {atMax && <p className="text-xs text-[var(--rd-color-text-muted)]">You can invite up to {maxInvites} people at once.</p>}
      </div>
      <div role="status" aria-live="polite" className="sr-only">
        {announcement}
      </div>
    </div>
  );
}

const resultRow =
  "flex min-h-11 cursor-default items-center gap-3 rounded-[var(--rd-radius-control)] px-2 py-1.5 text-sm outline-none " +
  "text-[var(--rd-color-text-default)] data-[hovered]:bg-[var(--rd-color-surface-subtle)] data-[focused]:bg-[var(--rd-color-surface-subtle)] " +
  "data-[focus-visible]:ring-2 data-[focus-visible]:ring-[var(--rd-color-focus-ring)]";

// Generated by rdloom codegen from specs/invite-dialog.spec.json (v0.1.0).
// Do not edit. Change the spec and run `npm run gen`.

export const inviteDialogVariantValues = ["emails", "search", "list"] as const;

/** A dialog for inviting people, in three shapes: typed emails with a role on one compact line each, a search of a directory you pass, or a two-step pick-from-a-list with a role per person. Checks for format, duplicates and people who are already members, an error summary, an optional message and a submit button that says how many invitations it sends. Your onInvite does the work. UI permission is not security: the server must check again. */
export interface InviteDialogSpecProps {
  /**
   * emails: one compact line per person, typed email and role. search: look people up in a directory you pass and add them to a to-invite list. list: a two-step modal, pick people from a list, then give each a role.
   * @default "emails"
   */
  variant?: "emails" | "search" | "list";
  /**
   * The roles a person can be invited as. The description of a role shows in the open list of the role select.
   */
  roles: Array<{ id: string; label: string; description?: string }>;
  /**
   * The id of the role each new row starts with. Defaults to the first role.
   */
  defaultRole?: string;
  /**
   * Emails that are already members. Typing one is an error on that row. Compared without case.
   */
  existingEmails?: string[];
  /**
   * Rows the emails variant starts with, for example people to invite again. Without it there is one empty row.
   */
  defaultInvites?: Array<{ email: string; role?: string }>;
  /**
   * The directory for the search and list variants. In search it is what the search looks in unless onSearch is given; in list it is every person that can be picked.
   */
  people?: Array<{ id: string; name: string; email: string; avatarUrl?: string }>;
  /**
   * Search variant only: looks people up on your server as the person types. Return the matches; the latest query wins. Without it, people is filtered in the browser.
   */
  onSearch?: (query: string) => Array<{ id: string; name: string; email: string; avatarUrl?: string }> | Promise<Array<{ id: string; name: string; email: string; avatarUrl?: string }>>;
  /**
   * Rows shown before the list scrolls inside itself, with a fade at the edge that has more. The dialog never grows past 90% of the screen height.
   * @default 4
   */
  maxVisibleRows?: number;
  /**
   * The most people one send can hold. Add another is disabled at the limit and says so.
   * @default 10
   */
  maxInvites?: number;
  /**
   * The dialog's title, shown as its heading. Default: "Invite people"; the list variant shows "Select users" and then "Give user role".
   */
  title?: string;
  /**
   * One sentence under the title.
   */
  description?: string;
  /**
   * Offers an optional message that goes with every invitation, behind an "Add a message" switch. Set false to remove it entirely. The list variant never has one.
   * @default true
   */
  allowMessage?: boolean;
  /**
   * The label of the message field.
   * @default "Message (optional)"
   */
  messageLabel?: string;
  /**
   * The text of the submit button for a number of invitations. Default: "Send invitation" and "Send 3 invitations".
   */
  submitLabel?: (count: number) => string;
  /**
   * The status message announced once the dialog has closed after a send. Default: "3 invitations sent".
   */
  successMessage?: (count: number) => string;
  /**
   * Sends the invitations; yours, async. person is set when someone was picked from the directory. Resolve for success. Return { fieldErrors: { "invites[1].email": "..." } } to show a problem on a row, or { formError } for the whole form; a throw also keeps the dialog open.
   */
  onInvite: (invites: Array<{ email: string; role: string; person?: { id: string; name: string; email: string; avatarUrl?: string } }>, details: { message?: string }) => void | import("../form/form").SubmitResult | Promise<void | import("../form/form").SubmitResult>;
  /**
   * Called when the person cancels: the Cancel button or Escape.
   */
  onCancel?: () => void;
  /**
   * Called with false when the dialog closes after a cancel or a successful send. Needed with isOpen.
   */
  onOpenChange?: (isOpen: boolean) => void;
  /**
   * Controlled open state, for a dialog opened without a DialogTrigger.
   */
  isOpen?: boolean;
  /**
   * What the app allows: invite. Hidden renders nothing; disabled keeps the dialog but the submit button stays focusable with aria-disabled and the reason shown and read, and nothing is sent. This only changes what people see: the server must check again.
   */
  permissions?: import("../utils/permissions").Permissions<"invite">;
  /**
   * Extra class names for single parts, so you can restyle one part without editing the file. Keys: dialog, form, list, message, toggle, search, results, counter, actions, cancelButton, submitButton, reason, status.
   */
  classNames?: Partial<Record<"dialog" | "form" | "list" | "message" | "toggle" | "search" | "results" | "counter" | "actions" | "cancelButton" | "submitButton" | "reason" | "status", string>>;
}

export const inviteDialogDefaults = {
  variant: "emails",
  maxVisibleRows: 4,
  maxInvites: 10,
  allowMessage: true,
  messageLabel: "Message (optional)",
} as const;

export const inviteDialogMeta = {
  "name": "InviteDialog",
  "version": "0.1.0",
  "status": "experimental",
  "role": "dialog"
} as const;

