import { useState } from "react";
import { PromptInput } from "@rdloom/react";

// The simplest form: just a box and a Send button. Add the other buttons by passing the props for them.
export default function PromptInputExample() {
  const [sent, setSent] = useState<string[]>([]);
  return (
    <div className="flex w-[36rem] max-w-full flex-col gap-3">
      <PromptInput placeholder="Ask anything" onSubmit={(text) => setSent((s) => [...s, text])} />
      {sent.length > 0 && (
        <ul className="flex flex-col gap-1 text-sm">
          {sent.map((text, i) => (
            <li key={i}>You sent: {text}</li>
          ))}
        </ul>
      )}
    </div>
  );
}

import { useEffect, useRef, useState } from "react";
import { PromptInput, fileToAttachment, releaseAttachment, type PromptAttachment } from "@rdloom/react";

// onAttach turns on "Add photos & files" in the + menu. You own the list: add to it, remove from it, and clear it
// when the message is sent. fileToAttachment makes a small preview for pictures; releaseAttachment frees it.
export default function PromptInputWithAttachmentsExample() {
  const [files, setFiles] = useState<PromptAttachment[]>([]);
  const [sent, setSent] = useState<string[]>([]);
  const latest = useRef(files);
  latest.current = files;
  useEffect(() => () => latest.current.forEach(releaseAttachment), []);

  return (
    <div className="flex w-[36rem] max-w-full flex-col gap-3">
      <PromptInput
        placeholder="Ask anything"
        accept="image/*,.pdf,.txt"
        attachments={files}
        onAttach={(chosen) => setFiles((list) => [...list, ...chosen.map(fileToAttachment)])}
        onRemoveAttachment={(id) =>
          setFiles((list) => {
            list.filter((a) => a.id === id).forEach(releaseAttachment);
            return list.filter((a) => a.id !== id);
          })
        }
        onSubmit={(text, attached) => {
          setSent((s) => [...s, `${text || "(no text)"} + ${attached.length} file${attached.length === 1 ? "" : "s"}`]);
          setFiles([]); // the files went with the message
        }}
      />
      {sent.length > 0 && (
        <ul className="flex flex-col gap-1 text-sm">
          {sent.map((line, i) => (
            <li key={i}>You sent: {line}</li>
          ))}
        </ul>
      )}
    </div>
  );
}

import { useState } from "react";
import { GlobeIcon, ImageIcon, PromptInput, SparkleIcon } from "@rdloom/react";

// The + menu can hold your own tools next to "Add photos & files". endContent puts a control of yours on the
// right, and onVoice adds the microphone button.
export default function PromptInputWithToolsExample() {
  const [listening, setListening] = useState(false);
  const [think, setThink] = useState(false);
  const [note, setNote] = useState("Nothing chosen yet.");

  return (
    <div className="flex w-[36rem] max-w-full flex-col gap-3">
      <PromptInput
        placeholder="Ask anything"
        onAttach={() => setNote("You chose Add photos & files.")}
        actions={[
          { id: "image", label: "Create image", description: "Visualize anything", icon: <ImageIcon className="size-5" />, onSelect: () => setNote("You chose Create image.") },
          { id: "search", label: "Web search", description: "Find real-time news and info", icon: <GlobeIcon className="size-5" />, onSelect: () => setNote("You chose Web search.") },
        ]}
        onVoice={() => setListening((v) => !v)}
        isListening={listening}
        endContent={
          <button
            type="button"
            aria-pressed={think}
            onClick={() => setThink((v) => !v)}
            className="flex h-10 items-center gap-1.5 rounded-full px-3 text-sm text-[var(--rd-color-text-muted)] outline-none hover:bg-[var(--rd-color-surface-selected)] hover:text-[var(--rd-color-text-default)] focus-visible:ring-2 focus-visible:ring-[var(--rd-color-focus-ring)] aria-pressed:bg-[var(--rd-color-surface-selected)] aria-pressed:text-[var(--rd-color-action-primary)]"
          >
            <SparkleIcon className="size-4" />
            Think
          </button>
        }
        onSubmit={(text) => setNote(`You sent: ${text}${think ? " (thinking on)" : ""}`)}
      />
      <p role="status" className="text-sm text-[var(--rd-color-text-muted)]">
        {note}
        {listening && " Listening…"}
      </p>
    </div>
  );
}

import { useState } from "react";
import { PromptInput } from "@rdloom/react";

// While a reply is on its way the Send button becomes Stop and sending is blocked.
export default function PromptInputStreamingExample() {
  const [streaming, setStreaming] = useState(true);
  return (
    <div className="w-[36rem] max-w-full">
      <PromptInput placeholder="Ask anything" isStreaming={streaming} onStop={() => setStreaming(false)} onSubmit={() => setStreaming(true)} />
    </div>
  );
}

