// Do not edit. Change the spec and run `npm run gen`.

/** Shows an assistant's reply as formatted text: headings, lists, tables, code, links and source markers. It is safe for text you do not control and for text that is still arriving. */
export interface ResponseSpecProps {
  /**
   * The reply, as markdown.
   */
  children: string;
  /**
   * True while the reply is still arriving. Shows a caret and tells assistive technology the content is changing.
   * @default false
   */
  isStreaming?: boolean;
  /**
   * Sources for the [1], [2] markers in the text. A marker with no matching source stays as plain text.
   */
  citations?: import("../utils/ai").CitationPart[];
  /**
   * Level of the reply's first heading (a # line), 2 to 6. Replies sit inside a page, so it starts at 3.
   * @default 3
   */
  headingLevel?: number;
}

export const responseDefaults = {
  isStreaming: false,
  headingLevel: 3,
} as const;

