// Do not edit. Change the spec and run `npm run gen`.

import type { ReactNode } from "react";

export const scrollAreaOrientationValues = ["vertical", "horizontal", "both"] as const;

/** A scrollable region with a thin themed scrollbar, reachable by keyboard, with optional fades at the edges that still have content. */
export interface ScrollAreaSpecProps {
  /**
   * The directions that scroll.
   * @default "vertical"
   */
  orientation?: "vertical" | "horizontal" | "both";
  /**
   * Accessible name of the region. Required unless aria-labelledby points at a heading.
   */
