/** A thin line that divides content, horizontal or vertical, with an optional label in the middle such as "or". */
export interface SeparatorSpecProps {
  /**
   * Direction of the line. A vertical one needs a parent with a height.
   * @default "horizontal"
   */
  orientation?: "horizontal" | "vertical";
  /**
   * Short text in the middle of a horizontal line, e.g. "or".
   */
