import { forwardRef, type CSSProperties, type HTMLAttributes } from "react";
import { shuttleBorderDefaults, type ShuttleBorderSpecProps } from "../generated/shuttle-border.types";
import { cx } from "../utils/cx";

// Plain markup with no hooks, so it also works in a React Server Component.

export interface ShuttleBorderProps
  extends ShuttleBorderSpecProps,
    Omit<HTMLAttributes<HTMLDivElement>, keyof ShuttleBorderSpecProps | "className"> {
  className?: string;
}

/**
 * A point of light that runs around the edge of whatever is inside, like the shuttle of a loom
 * crossing the threads. Give it the radius and background you want through className.
 */
export const ShuttleBorder = forwardRef<HTMLDivElement, ShuttleBorderProps>(function ShuttleBorder(
  {
    children,
    color,
    duration = shuttleBorderDefaults.duration,
    borderWidth = shuttleBorderDefaults.borderWidth,
    isPaused = shuttleBorderDefaults.isPaused,
    className,
    style,
    ...rest
  },
  ref,
) {
  const vars: Record<string, string | number> = { "--rdm-d": `${duration}s`, "--rdm-w": `${borderWidth}px` };
  if (color) vars["--rdm-c"] = color;
  return (
    <div
      {...rest}
      ref={ref}
      data-rdm-paused={isPaused || undefined}
      className={cx("relative rounded-[var(--rd-radius-overlay)]", className)}
      style={{ ...(vars as CSSProperties), ...style }}
    >
      <span aria-hidden="true" className="rdm-shuttle" />
      {children}
    </div>
  );
});

// Generated by rdloom codegen from specs/shuttle-border.spec.json (v0.1.0).
// Do not edit. Change the spec and run `npm run gen`.

import type { ReactNode } from "react";

/** A point of light that runs around the edge of whatever is inside, like the shuttle of a loom crossing the threads. Wrap a card, an input or a button; give it your radius and background. */
export interface ShuttleBorderSpecProps {
  /**
   * The content the light runs around.
   */
  children: ReactNode;
  /**
   * Colour of the light, any CSS colour. Defaults to the action colour.
   */
  color?: string;
  /**
   * Seconds for one lap.
   * @default 4
   */
  duration?: number;
  /**
   * Thickness of the light in pixels.
   * @default 1.5
   */
  borderWidth?: number;
  /**
   * Stops the animation. Moving content that lasts more than five seconds should be stoppable.
   * @default false
   */
  isPaused?: boolean;
  /**
   * Classes for the wrapper: set its radius, background and border here.
   */
  className?: string;
}

export const shuttleBorderDefaults = {
  duration: 4,
  borderWidth: 1.5,
  isPaused: false,
} as const;

export const shuttleBorderMeta = {
  "name": "ShuttleBorder",
  "version": "0.1.0",
  "status": "experimental",
  "role": "none"
} as const;

