import type { ReactNode } from "react";
import { resolvePermission, type PermissionValue } from "../utils/permissions";

// The navigation of a dashboard, as data: groups of items, each of which may open a short list of
// sub-items. The shell draws it; the functions here answer questions about it.

export interface NavItem {
  /** A stable id. The current page is named by it. */
  id: string;
  label: string;
  /** Where it goes. Without one the item is a button and `onNavigate` does the work. */
  href?: string;
  /** A 16-unit icon. Without one the first letter of the label is shown (the collapsed sidebar shows only icons). */
  icon?: ReactNode;
  /** A small count or word beside the label, e.g. 3 or "New". */
  badge?: string | number;
  /** One level of sub-items. The item itself then opens and closes the list instead of going anywhere. */
  children?: NavItem[];
  /**
   * What the app allows for this item: "allow" (default), "disabled" (shown, not followed, with the reason in a tooltip) or
   * "hidden" (not drawn). This only changes what people see; the server must check access again.
   */
  permission?: PermissionValue;
}

export interface NavGroup {
  /** A heading for the group, e.g. "Workspace". Omit it for a group without one. */
  label?: string;
  items: NavItem[];
}

export interface ShellUser {
  name: string;
  email?: string;
  avatarUrl?: string;
  /** Entries of the account menu, e.g. Settings and Sign out. */
  menu?: Array<{ id: string; label: string; onSelect: () => void; variant?: "default" | "danger" }>;
}

/** An organisation, workspace or project the person can switch between. */
export interface ShellTeam {
  id?: string;
  name: string;
  /** A second line, e.g. the plan: "Enterprise". */
  description?: string;
  /** Your logo, 20 px or so. Without one the first letter of the name is shown. */
  logo?: ReactNode;
}

/** Every item in order, sub-items included. */
export function flattenNav(groups: NavGroup[]): NavItem[] {
  return groups.flatMap((g) => g.items.flatMap((i) => [i, ...(i.children ?? [])]));
}

/** The item with this id, wherever it is. */
export const findNavItem = (groups: NavGroup[], id: string | undefined): NavItem | undefined => (id === undefined ? undefined : flattenNav(groups).find((i) => i.id === id));

/** The top-level item that holds the current page: itself, or the parent of the current sub-item. */
export function currentTopLevel(groups: NavGroup[], currentId: string | undefined): NavItem | undefined {
  if (currentId === undefined) return undefined;
  for (const group of groups) {
    for (const item of group.items) {
      if (item.id === currentId || item.children?.some((c) => c.id === currentId)) return item;
    }
  }
  return undefined;
}

/** "Customers" for a page, or "Workspace / Customers" style trail of labels from the group to the item. */
export function trailOf(groups: NavGroup[], currentId: string | undefined): string[] {
  if (currentId === undefined) return [];
  for (const group of groups) {
    for (const item of group.items) {
      if (item.id === currentId) return [item.label];
      const child = item.children?.find((c) => c.id === currentId);
      if (child) return [item.label, child.label];
    }
  }
  return [];
}

/** The letter shown for an item with no icon. */
export const initialOf = (label: string) => (label.trim()[0] ?? "?").toUpperCase();

/** A badge as the text a screen reader should hear after the label. */
export const badgeText = (badge: string | number | undefined) => (badge === undefined || badge === "" ? "" : typeof badge === "number" ? `${badge}` : badge);

/** What a navigation item shows: its answer for the current person. */
export const navPermission = (item: NavItem) => resolvePermission(item.permission);

/**
 * The navigation as people may see it: hidden items are removed, a parent whose children are all hidden goes too,
 * and a group left with nothing is dropped. Disabled items stay.
 */
export function visibleNav(groups: NavGroup[]): NavGroup[] {
  const result: NavGroup[] = [];
  for (const group of groups) {
    const items: NavItem[] = [];
    for (const item of group.items) {
      if (!navPermission(item).isVisible) continue;
      if (item.children?.length) {
        const children = item.children.filter((c) => navPermission(c).isVisible);
        if (children.length === 0) continue;
        items.push({ ...item, children });
      } else items.push(item);
    }
    if (items.length) result.push({ ...group, items });
  }
  return result;
}

/** The same rules for one flat list of items (a top navigation): hidden items go, and a parent whose children are all hidden goes too. */
export const visibleItems = (items: NavItem[]): NavItem[] => visibleNav([{ items }])[0]?.items ?? [];

"use client";

import { forwardRef, useEffect, useId, useState, type ReactNode } from "react";
import { Button as AriaButton, Link as AriaLink } from "react-aria-components";
import { sidebarDefaults, type SidebarSpecProps } from "../generated/sidebar.types";
import { Avatar } from "../avatar/avatar";
import { Menu, MenuItem, MenuTrigger } from "../menu/menu";
import { Tooltip, TooltipTrigger } from "../tooltip/tooltip";
import { cx } from "../utils/cx";
import { ChevronRightIcon, ChevronsUpDownIcon, SearchIcon, SidebarIcon } from "../utils/icons";
import { badgeText, currentTopLevel, initialOf, navPermission, visibleNav, type NavGroup, type NavItem, type ShellTeam, type ShellUser } from "./nav";

export interface SidebarProps extends SidebarSpecProps {
  className?: string;
}

/** The parts of the sidebar that take a class name of their own. */
export type SidebarSlot = "root" | "header" | "team-switcher" | "search" | "nav" | "group" | "item" | "sub-list" | "footer" | "collapse" | "account";
export type SidebarClassNames = Partial<Record<SidebarSlot, string>>;

const linkBase =
  "relative flex w-full items-center gap-3 rounded-[var(--rd-radius-control)] px-3 py-1.5 text-start text-sm outline-none transition-colors " +
  "min-h-[var(--rd-size-control-sm)] text-[var(--rd-color-text-muted)] data-[hovered]:bg-[var(--rd-color-surface-subtle)] data-[hovered]:text-[var(--rd-color-text-default)] " +
  "data-[focus-visible]:ring-2 data-[focus-visible]:ring-[var(--rd-color-focus-ring)] motion-reduce:transition-none";
// The current page: a soft tinted background, the accent color on its icon, and a heavier label. It is also aria-current.
// No thick bar on one edge: the tint and the weight carry it.
const linkCurrent = "bg-[var(--rd-color-surface-selected)] font-medium !text-[var(--rd-color-text-default)]";

type RenderLink = NonNullable<SidebarSpecProps["renderLink"]>;

export interface NavProps {
  groups: NavGroup[];
  currentId?: string;
  collapsed: boolean;
  label: string;
  onNavigate?: (item: NavItem) => void;
  renderLink?: RenderLink;
  /** Called after an item is chosen: the mobile menu closes itself with it. */
  onPick?: () => void;
  /** Ask the sidebar to open (a collapsed parent has nowhere to show its sub-items). */
  onExpand?: () => void;
  /** Class names for the parts: nav, group, item and sub-list are drawn here. */
  classNames?: SidebarClassNames;
}

function Badge({ value, collapsed }: { value: string | number | undefined; collapsed: boolean }) {
  const text = badgeText(value);
  if (!text) return null;
  return (
    <>
      {/* Spoken after the label. Drawn as a small pill, or as a dot when the sidebar is folded and there is no room for it. */}
      <span className="sr-only">, {text}</span>
      {collapsed ? (
        <span aria-hidden="true" className="absolute end-2 top-1.5 size-2 rounded-full bg-[var(--rd-color-action-primary)] ring-2 ring-[var(--rd-color-surface-default)]" />
      ) : (
        <span
          aria-hidden="true"
          className="ms-auto inline-flex min-w-5 items-center justify-center rounded-full bg-[var(--rd-color-surface-subtle)] px-1.5 text-[11px] leading-5 font-medium text-[var(--rd-color-text-default)] tabular-nums"
        >
          {text}
        </span>
      )}
    </>
  );
}

function ItemBody({ item, collapsed, nested }: { item: NavItem; collapsed: boolean; nested?: boolean }) {
  return (
    <>
      {/* A sub-item sits under its parent's icon, so it needs none; a top-level item without one gets its first letter. */}
      {(item.icon || !nested) && (
        <span aria-hidden="true" className="flex size-4 shrink-0 items-center justify-center text-[var(--rd-color-text-muted)] group-data-[current]/nav:text-[var(--rd-color-action-primary)]">
          {item.icon ?? <span className="flex size-5 items-center justify-center rounded bg-[var(--rd-color-surface-subtle)] text-[11px] font-semibold">{initialOf(item.label)}</span>}
        </span>
      )}
      <span className={cx("min-w-0 flex-1 truncate", collapsed && "sr-only")}>{item.label}</span>
      <Badge value={item.badge} collapsed={collapsed} />
    </>
  );
}

function Entry({ item, nested, current, parentOf, ...nav }: { item: NavItem; nested?: boolean; current: boolean; parentOf: boolean } & NavProps) {
  const { collapsed, onNavigate, renderLink, onPick, onExpand, classNames } = nav;
  const listId = useId();
  const [open, setOpen] = useState(parentOf);
  useEffect(() => {
    if (parentOf) setOpen(true);
  }, [parentOf]);
  const iconOnly = collapsed && !nested;
  const className = cx(linkBase, "group/nav", current && linkCurrent, parentOf && !current && "font-medium !text-[var(--rd-color-text-default)]", iconOnly && "justify-center px-0", nested && "min-h-8 py-1", classNames?.item);
  const body = <ItemBody item={item} collapsed={iconOnly} nested={nested} />;

  const permission = navPermission(item);
  if (permission.isDisabled) {
    // Shown, focusable and explained, but it goes nowhere.
    const reason = permission.reason;
    const button = (
      <AriaButton aria-disabled="true" aria-describedby={reason ? listId : undefined} onPress={() => {}} className={cx(className, "cursor-not-allowed opacity-50")}>
        {body}
      </AriaButton>
    );
    return (
      <li>
        {reason || iconOnly ? (
          <TooltipTrigger delay={300}>
            {button}
            <Tooltip placement="end">{reason ? (iconOnly ? `${item.label}: ${reason}` : reason) : item.label}</Tooltip>
          </TooltipTrigger>
        ) : (
          button
        )}
        {reason && (
          <span id={listId} className="sr-only">
            {reason}
          </span>
        )}
      </li>
    );
  }

  if (item.children?.length) {
    return (
      <li>
        <AriaButton
          aria-expanded={open && !collapsed}
          aria-controls={listId}
          onPress={() => {
            if (collapsed) {
              onExpand?.();
              setOpen(true);
            } else setOpen((v) => !v);
          }}
          className={cx(className)}
        >
          {body}
          {!collapsed && <ChevronRightIcon className={cx("size-4 shrink-0 text-[var(--rd-color-text-muted)] transition-transform motion-reduce:transition-none", open ? "rotate-90" : "")} />}
        </AriaButton>
        {/* Closed lists stay in the page, hidden, so their links are still there for search and for the current page's own parent. */}
        <ul id={listId} hidden={!open || collapsed} className={cx("mt-0.5 ms-5 flex flex-col gap-0.5 border-s border-[var(--rd-color-border-default)] ps-2", classNames?.["sub-list"])}>
          {item.children.map((child) => (
            <Entry key={child.id} item={child} nested current={nav.currentId === child.id} parentOf={false} {...nav} />
          ))}
        </ul>
      </li>
    );
  }

  const choose = () => {
    onNavigate?.(item);
    onPick?.();
  };

  if (renderLink) {
    return <li>{renderLink({ item, className: cx(className, "data-[hovered]:bg-[var(--rd-color-surface-subtle)]"), children: body, isCurrent: current, onClick: choose })}</li>;
  }

  const control = item.href ? (
    <AriaLink href={item.href} aria-current={current ? "page" : undefined} data-current={current || undefined} onPress={choose} className={className}>
      {body}
    </AriaLink>
  ) : (
    <AriaButton aria-current={current ? "page" : undefined} data-current={current || undefined} onPress={choose} className={className}>
      {body}
    </AriaButton>
  );

  return (
    <li>
      {iconOnly ? (
        <TooltipTrigger delay={300}>
          {control}
          <Tooltip placement="end">{item.label}</Tooltip>
        </TooltipTrigger>
      ) : (
        control
      )}
    </li>
  );
}

export function NavList(props: NavProps) {
  const { currentId, collapsed, label, classNames } = props;
  // What the app hides is not drawn, and nothing that is empty is left behind.
  const groups = visibleNav(props.groups);
  const top = currentTopLevel(groups, currentId);
  return (
    <nav aria-label={label} className={cx("flex min-h-0 flex-1 flex-col gap-5 overflow-y-auto px-3 py-2", classNames?.nav)}>
      {groups.map((group, g) => (
        <div key={g} className={cx("flex flex-col gap-1", classNames?.group)}>
          {group.label &&
            (collapsed ? (
              <div role="separator" className="mx-2 my-1 border-t border-[var(--rd-color-border-default)]" />
            ) : (
              <p className="px-3 pb-1 text-xs font-medium text-[var(--rd-color-text-muted)]">{group.label}</p>
            ))}
          <ul className="flex flex-col gap-0.5">
            {group.items.map((item) => (
              <Entry key={item.id} item={item} current={currentId === item.id} parentOf={top?.id === item.id && top.id !== currentId} {...props} groups={groups} />
            ))}
          </ul>
        </div>
      ))}
    </nav>
  );
}

function TeamLogo({ team }: { team: ShellTeam }) {
  return (
    <span aria-hidden="true" className="flex size-8 shrink-0 items-center justify-center rounded-[var(--rd-radius-control)] bg-[var(--rd-color-text-default)] text-sm font-semibold text-[var(--rd-color-surface-default)]">
      {team.logo ?? initialOf(team.name)}
    </span>
  );
}

/** The name of the organisation or workspace at the top of the sidebar. With several to choose from it is a menu. */
export function TeamSwitcher({ team, teams, onSelect, collapsed, className: extra }: { team: ShellTeam; teams?: ShellTeam[]; onSelect?: (team: ShellTeam) => void; collapsed: boolean; className?: string }) {
  const body = (
    <>
      <TeamLogo team={team} />
      {!collapsed && (
        <span className="flex min-w-0 flex-1 flex-col text-start leading-tight">
          <span className="truncate text-sm font-semibold text-[var(--rd-color-text-default)]">{team.name}</span>
          {team.description && <span className="truncate text-xs text-[var(--rd-color-text-muted)]">{team.description}</span>}
        </span>
      )}
      {!collapsed && teams && teams.length > 1 && <ChevronsUpDownIcon className="size-4 shrink-0 text-[var(--rd-color-text-muted)]" />}
    </>
  );
  const classes = cx(
    "flex w-full items-center gap-2.5 rounded-[var(--rd-radius-control)] p-1.5 outline-none data-[focus-visible]:ring-2 data-[focus-visible]:ring-[var(--rd-color-focus-ring)]",
    collapsed && "justify-center",
    extra,
  );
  if (!teams || teams.length < 2) return <div className={classes}>{body}</div>;
  return (
    <MenuTrigger>
      <AriaButton aria-label={`Switch workspace, current: ${team.name}`} className={cx(classes, "data-[hovered]:bg-[var(--rd-color-surface-subtle)]")}>
        {body}
      </AriaButton>
      <Menu placement="bottom start" aria-label="Workspaces">
        {teams.map((t) => (
          <MenuItem key={t.id ?? t.name} id={t.id ?? t.name} textValue={t.name} onAction={() => onSelect?.(t)}>
            {t.name}
          </MenuItem>
        ))}
      </Menu>
    </MenuTrigger>
  );
}

export function AccountMenu({ user, collapsed, className: extra }: { user: ShellUser; collapsed: boolean; className?: string }) {
  const trigger = (
    <AriaButton
      aria-label={`Account menu, ${user.name}`}
      className={cx(
        "flex w-full items-center gap-3 rounded-[var(--rd-radius-control)] p-2 text-start outline-none data-[hovered]:bg-[var(--rd-color-surface-subtle)] data-[focus-visible]:ring-2 data-[focus-visible]:ring-[var(--rd-color-focus-ring)]",
        collapsed && "justify-center",
      )}
    >
      <Avatar name={user.name} src={user.avatarUrl} size="sm" decorative />
      {!collapsed && (
        <span className="flex min-w-0 flex-1 flex-col">
          <span className="truncate text-sm font-medium text-[var(--rd-color-text-default)]">{user.name}</span>
          {user.email && <span className="truncate text-xs text-[var(--rd-color-text-muted)]">{user.email}</span>}
        </span>
      )}
      {!collapsed && <ChevronsUpDownIcon className="size-4 shrink-0 text-[var(--rd-color-text-muted)]" />}
    </AriaButton>
  );
  if (!user.menu?.length) return <div className={cx("p-1", extra)}>{trigger}</div>;
  return (
    <div className={cx("border-t border-[var(--rd-color-border-default)] p-2", extra)}>
      <MenuTrigger>
        {trigger}
        <Menu placement="top start">
          {user.menu.map((entry) => (
            <MenuItem key={entry.id} id={entry.id} variant={entry.variant} onAction={entry.onSelect}>
              {entry.label}
            </MenuItem>
          ))}
        </Menu>
      </MenuTrigger>
    </div>
  );
}

const appearances = {
  bordered: "border-e border-[var(--rd-color-border-default)] bg-[var(--rd-color-surface-default)]",
  subtle: "bg-[var(--rd-color-surface-subtle)]",
  inset: "bg-transparent",
  floating: "m-2 h-[calc(100%-1rem)] rounded-2xl border border-[var(--rd-color-border-default)] bg-[var(--rd-color-surface-raised)] [box-shadow:var(--rd-elevation-raised)]",
} as const;

/**
 * A sidebar of navigation: the team or product name at the top, grouped links (with one level of
 * sub-items and badges), an optional footer, and the signed-in person at the bottom. It can fold down
 * to icons. It fills the height of its parent and has no router of its own: items are links (with
 * `href`, or through `renderLink` for your router) or buttons (with `onNavigate`). It is only the
 * panel. For the full frame with a top bar and a phone menu use DashboardShell.
 */
export const Sidebar = forwardRef<HTMLDivElement, SidebarProps>(function Sidebar(
  {
    navigation,
    currentId,
    brand,
    team,
    teams,
    onTeamChange,
    user,
    footer,
    onSearch,
    searchLabel = sidebarDefaults.searchLabel,
    label = sidebarDefaults.label,
    onNavigate,
    renderLink,
    onPick,
    isCollapsed,
    defaultCollapsed = sidebarDefaults.defaultCollapsed,
    onCollapsedChange,
    collapsible = sidebarDefaults.collapsible,
    appearance = sidebarDefaults.appearance,
    classNames,
    className,
  },
  ref,
) {
  const [innerCollapsed, setInnerCollapsed] = useState(defaultCollapsed);
  const collapsed = isCollapsed ?? innerCollapsed;
  const setCollapsed = (next: boolean) => {
    if (isCollapsed === undefined) setInnerCollapsed(next);
    onCollapsedChange?.(next);
  };

  const toggle = (
    <AriaButton
      aria-label={collapsed ? "Expand sidebar" : "Collapse sidebar"}
      aria-expanded={!collapsed}
      onPress={() => setCollapsed(!collapsed)}
      className={cx(
        "flex min-h-[var(--rd-size-control-sm)] w-full items-center gap-3 rounded-[var(--rd-radius-control)] px-3 text-start text-sm text-[var(--rd-color-text-muted)] outline-none data-[hovered]:bg-[var(--rd-color-surface-subtle)] data-[hovered]:text-[var(--rd-color-text-default)] data-[focus-visible]:ring-2 data-[focus-visible]:ring-[var(--rd-color-focus-ring)]",
        collapsed && "justify-center px-0",
        classNames?.collapse,
      )}
    >
      <SidebarIcon className="size-4 shrink-0" />
      {!collapsed && <span className="truncate">Collapse</span>}
    </AriaButton>
  );

  return (
    <div
      ref={ref}
      data-collapsed={collapsed || undefined}
      data-appearance={appearance}
      className={cx(
        "flex h-full min-h-0 shrink-0 flex-col overflow-hidden transition-[width] duration-200 motion-reduce:transition-none",
        collapsed ? "w-[var(--rd-sidebar-rail,4.5rem)]" : "w-[var(--rd-sidebar-width,16rem)]",
        appearances[appearance],
        className,
        classNames?.root,
      )}
    >
      <div className={cx("flex h-14 shrink-0 items-center px-3", collapsed && "justify-center", classNames?.header)}>
        {team ? (
          <TeamSwitcher team={team} teams={teams} onSelect={onTeamChange} collapsed={collapsed} className={classNames?.["team-switcher"]} />
        ) : (
          !collapsed && <div className="min-w-0 flex-1 truncate px-1 text-[15px] font-semibold">{brand}</div>
        )}
      </div>
      {onSearch && (
        <div className={cx("px-3 pb-1", classNames?.search)}>
          {collapsed ? (
            <TooltipTrigger delay={300}>
              <AriaButton
                onPress={onSearch}
                aria-label={searchLabel}
                className="flex size-9 w-full items-center justify-center rounded-[var(--rd-radius-control)] text-[var(--rd-color-text-muted)] outline-none data-[hovered]:bg-[var(--rd-color-surface-subtle)] data-[focus-visible]:ring-2 data-[focus-visible]:ring-[var(--rd-color-focus-ring)]"
              >
                <SearchIcon className="size-4" />
              </AriaButton>
              <Tooltip placement="end">{searchLabel}</Tooltip>
            </TooltipTrigger>
          ) : (
            <AriaButton
              onPress={onSearch}
              className="flex h-9 w-full items-center gap-2 rounded-[var(--rd-radius-control)] border border-[var(--rd-color-border-default)] bg-[var(--rd-color-surface-default)] px-3 text-sm text-[var(--rd-color-text-muted)] outline-none data-[hovered]:border-[var(--rd-color-border-strong)] data-[focus-visible]:ring-2 data-[focus-visible]:ring-[var(--rd-color-focus-ring)]"
            >
              <SearchIcon className="size-4" />
              <span className="flex-1 truncate text-start">{searchLabel}</span>
            </AriaButton>
          )}
        </div>
      )}
      <NavList groups={navigation} currentId={currentId} label={label} collapsed={collapsed} onNavigate={onNavigate} renderLink={renderLink} onPick={onPick} onExpand={() => setCollapsed(false)} classNames={classNames} />
      {footer && !collapsed && <div className={cx("shrink-0 px-3 pb-2", classNames?.footer)}>{footer as ReactNode}</div>}
      {collapsible && (
        <div className="shrink-0 px-3 pb-2">
          {collapsed ? (
            <TooltipTrigger delay={300}>
              {toggle}
              <Tooltip placement="end">Expand sidebar</Tooltip>
            </TooltipTrigger>
          ) : (
            toggle
          )}
        </div>
      )}
      {user && <AccountMenu user={user} collapsed={collapsed} className={classNames?.account} />}
    </div>
  );
});

// Generated by rdloom codegen from specs/sidebar.spec.json (v0.1.0).
// Do not edit. Change the spec and run `npm run gen`.

import type { ReactNode } from "react";

export const sidebarAppearanceValues = ["bordered", "subtle", "floating", "inset"] as const;

/** A sidebar of navigation: the team or product name at the top, grouped links with sub-items and badges, an optional footer, and the signed-in person at the bottom. It can fold down to icons, and comes in four looks. It is only the panel; DashboardShell adds the top bar and the phone menu. */
export interface SidebarSpecProps {
  /**
   * The navigation as groups of items. An item may hold one level of sub-items. An item may carry a permission ("allow", "disabled", "hidden" or { state, reason }): hidden items, and groups or parents left with nothing, are not drawn or counted; disabled items stay as focusable, non-navigating entries (aria-disabled) with the reason in a tooltip.
   */
  navigation: import("../sidebar/nav").NavGroup[];
  /**
   * The id of the page you are on. It is marked as the current page (aria-current) and its parent opens.
   */
  currentId?: string;
  /**
   * Your logo or product name at the top. Ignored when a team is given.
   */
  brand?: ReactNode;
  /**
   * The organisation or workspace shown at the top, with its logo and a second line such as the plan. Replaces brand.
   */
  team?: import("../sidebar/nav").ShellTeam;
  /**
   * Other workspaces to switch to. With two or more the team becomes a menu.
   */
  teams?: import("../sidebar/nav").ShellTeam[];
  /**
   * Called with the workspace the person chose.
   */
  onTeamChange?: (team: import("../sidebar/nav").ShellTeam) => void;
  /**
   * The signed-in person: shown at the bottom with an account menu.
   */
  user?: import("../sidebar/nav").ShellUser;
  /**
   * Content above the account area, such as an upgrade card or a storage meter. It is hidden while the sidebar is folded.
   */
  footer?: ReactNode;
  /**
   * Shows a search button under the name and calls this when it is pressed, e.g. to open a command palette.
   */
  onSearch?: () => void;
  /**
   * Text and accessible name of the search button.
   * @default "Search"
   */
  searchLabel?: string;
  /**
   * Accessible name of the navigation.
   * @default "Main navigation"
   */
  label?: string;
  /**
   * Called with the item when one is chosen. Items without an href use this to do their work.
   */
  onNavigate?: (item: import("../sidebar/nav").NavItem) => void;
  /**
   * Draw items as your router's link. Return the link with the given className and children; call onClick when chosen. Without it, items with an href are plain links.
   */
  renderLink?: (props: { item: import("../sidebar/nav").NavItem; className: string; children: import("react").ReactNode; isCurrent: boolean; onClick: () => void }) => import("react").ReactNode;
  /**
   * Called after any item is chosen. Use it to close a sheet that holds the sidebar on a phone.
   */
  onPick?: () => void;
  /**
   * Controlled: whether the sidebar is folded down to icons.
   */
  isCollapsed?: boolean;
  /**
   * Start folded down.
   * @default false
   */
  defaultCollapsed?: boolean;
  /**
   * Called when the person folds or opens the sidebar. Save it if you want it remembered.
   */
  onCollapsedChange?: (collapsed: boolean) => void;
  /**
   * Show the Collapse button at the bottom. Turn it off when you fold the sidebar from somewhere else, such as a top bar.
   * @default true
   */
  collapsible?: boolean;
  /**
   * Class names for the parts of the sidebar, by slot name, added after the built-in ones so you can restyle one part without editing the file. Slots: root, header, team-switcher, search, nav, group, item, sub-list, footer, collapse, account.
   */
  classNames?: Partial<Record<"root" | "header" | "team-switcher" | "search" | "nav" | "group" | "item" | "sub-list" | "footer" | "collapse" | "account", string>>;
  /**
   * bordered: a line on the inner edge. subtle: a tinted panel with no line. floating: a rounded raised card with a margin around it. inset: no line and no fill, for a sidebar that sits on a tinted page beside an inset page card (DashboardShell draws that page card).
   * @default "bordered"
   */
  appearance?: "bordered" | "subtle" | "floating" | "inset";
}

export const sidebarDefaults = {
  searchLabel: "Search",
  label: "Main navigation",
  defaultCollapsed: false,
  collapsible: true,
  appearance: "bordered",
} as const;

export const sidebarMeta = {
  "name": "Sidebar",
  "version": "0.1.0",
  "status": "experimental",
  "role": "navigation"
} as const;

