import { Sparkline } from "@rdloom/react";

// Fixed, repeatable series so the preview never changes between renders.
const noise = (i: number, k: number) => Math.sin(i * 12.9898 + k * 78.233) * 0.5 + Math.sin(i * 4.1 + k) * 0.5;

// Daily revenue in thousands: lower at weekends, on top of slow growth, 60 days.
const revenue = Array.from({ length: 60 }, (_, i) => {
  const weekend = i % 7 === 5 || i % 7 === 6 ? -6 : 0;
  return Math.round((42 + i * 0.35 + weekend + noise(i, 1) * 3) * 10) / 10;
});

// Give it a label when the picture carries information the page doesn't say in words.
export default function SparklineLineExample() {
  const last = revenue[revenue.length - 1];
  const change = Math.round(((last - revenue[0]) / revenue[0]) * 100);
  return (
    <div className="flex w-full justify-center">
      <div className="flex w-[36rem] max-w-full flex-col gap-3">
        <div className="flex items-baseline justify-between gap-4">
          <span className="text-sm text-[var(--rd-color-text-muted)]">Daily revenue, last 60 days</span>
          <span className="flex items-baseline gap-2 tabular-nums">
            <span className="text-2xl font-semibold">${last}K</span>
            <span className="text-sm text-[var(--rd-color-feedback-success)]">+{change}%</span>
          </span>
        </div>
        <Sparkline responsive width={576} height={96} data={revenue} label={`Daily revenue, last 60 days: from ${revenue[0]}K to ${last}K, lower on weekends`} />
      </div>
    </div>
  );
}

import { Sparkline } from "@rdloom/react";

// Fixed, repeatable series so the preview never changes between renders.
const noise = (i: number, k: number) => Math.sin(i * 12.9898 + k * 78.233) * 0.5 + Math.sin(i * 4.1 + k) * 0.5;

// New signups per day over 90 days, trending up with a launch bump around day 45.
const signups = Array.from({ length: 90 }, (_, i) =>
  Math.max(0, Math.round(120 + i * 2.1 + (i > 45 && i < 55 ? 60 : 0) + noise(i, 2) * 18)),
);

export default function SparklineAreaExample() {
  const total = signups.reduce((n, v) => n + v, 0);
  const lastWeek = signups.slice(-7).reduce((n, v) => n + v, 0);
  const prevWeek = signups.slice(-14, -7).reduce((n, v) => n + v, 0);
  const change = Math.round(((lastWeek - prevWeek) / prevWeek) * 100);
  return (
    <div className="flex w-full justify-center">
      <div className="flex w-[36rem] max-w-full flex-col gap-3">
        <div className="flex items-baseline justify-between gap-4">
          <span className="text-sm text-[var(--rd-color-text-muted)]">Signups, last 90 days</span>
          <span className="flex items-baseline gap-2 tabular-nums">
            <span className="text-2xl font-semibold">{total.toLocaleString("en-US")}</span>
            <span className="text-sm text-[var(--rd-color-feedback-success)]">+{change}% vs previous week</span>
          </span>
        </div>
        <Sparkline type="area" responsive width={576} height={96} data={signups} label={`Signups per day, last 90 days: from ${signups[0]} to ${signups[89]}, with a bump after day 45`} />
      </div>
    </div>
  );
}

import { Sparkline } from "@rdloom/react";

// Fixed, repeatable series so the preview never changes between renders.
const noise = (i: number, k: number) => Math.sin(i * 12.9898 + k * 78.233) * 0.5 + Math.sin(i * 4.1 + k) * 0.5;

// Orders per day for 45 days, busier on weekdays.
const orders = Array.from({ length: 45 }, (_, i) => {
  const weekend = i % 7 === 5 || i % 7 === 6;
  return Math.round((weekend ? 38 : 72) + noise(i, 3) * 10);
});

export default function SparklineBarExample() {
  const avg = Math.round(orders.reduce((n, v) => n + v, 0) / orders.length);
  return (
    <div className="flex w-full justify-center">
      <div className="flex w-[36rem] max-w-full flex-col gap-3">
        <div className="flex items-baseline justify-between gap-4">
          <span className="text-sm text-[var(--rd-color-text-muted)]">Orders per day, last 45 days</span>
          <span className="flex items-baseline gap-2 tabular-nums">
            <span className="text-2xl font-semibold">{avg}</span>
            <span className="text-sm text-[var(--rd-color-text-muted)]">orders a day on average</span>
          </span>
        </div>
        <Sparkline type="bar" responsive width={576} height={80} data={orders} label={`Orders per day, last 45 days: about ${avg} on average, fewer at weekends`} />
      </div>
    </div>
  );
}

import { Sparkline } from "@rdloom/react";

// Fixed, repeatable series so the preview never changes between renders.
const noise = (i: number, k: number) => Math.sin(i * 12.9898 + k * 78.233) * 0.5 + Math.sin(i * 4.1 + k) * 0.5;

const series = (n: number, base: number, slope: number, amp: number, k: number) =>
  Array.from({ length: n }, (_, i) => Math.round((base + slope * i + noise(i, k) * amp) * 100) / 100);

// Color says "good", "bad" or "just a trend", but the words around it still say so: never rely on color alone.
const rows = [
  { label: "Revenue", value: "$58.2K", change: "+24%", note: "Up", color: "primary" as const, data: series(60, 42, 0.28, 3, 1) },
  { label: "Active users", value: "12,480", change: "+11%", note: "Up", color: "success" as const, data: series(60, 9000, 58, 220, 2) },
  { label: "Churn", value: "2.4%", change: "+0.9 pt", note: "Rising", color: "danger" as const, data: series(60, 1.4, 0.017, 0.12, 3) },
