export const statVariantValues = ["plain", "card"] as const;
export const statSizeValues = ["sm", "md", "lg"] as const;

/** A key number with its label and context: a value, an optional change over time and an optional small trend graphic. Unframed: place it in a Card or a grid. */
export interface StatSpecProps {
  /**
   * What the number measures, e.g. "Monthly revenue".
